    $cols = @('#ff3fa4', '#22e6ff', '#9a5cff', '#ffb020')
    for ($i = 0; $i -lt 28; $i++) {
        $g = New-BfxGlow (Get-BfxRnd $S 20 60) (Get-BfxPick $S $cols) 0.4; $tf = Set-BfxTransforms $g
