    for ($i = 0; $i -lt 10; $i++) {
        $c = New-BfxGlow (Get-BfxRnd $S 70 140) '#c8a46e' 0.28; $tf = Set-BfxTransforms $c
        $per = Get-BfxRnd $S 6 12
