        $st = New-BfxEllipse 1.4 1.4 (New-BfxBrush '#ffffff' 0.45); $tf = Set-BfxTransforms $st
        Add-BfxItem $S $st -Top (Get-BfxRnd $S 0 $H) -Speed (-15) -Phase (Get-BfxRnd $S) -T $tf.T -Margin 5
