            if ($o[2]) { Start-BfxAnim $st.T $global:BfxP.Y -25 25 1.6 0 -Reverse -Ease; Start-BfxAnim $st.R $global:BfxP.A 20 -20 1.6 0.25 -Reverse -Ease }
        }
