    } ($H * 2.0)
    Complete-BfxStage $S
}

function global:Add-BfxContrails {
    param([string]$BannerName, [double]$BannerH)
    $S = New-BfxStage $BannerName; if (-not $S) { return }; $H = $BannerH
    for ($i = 0; $i -lt 3; $i++) {
        $jet = New-Object System.Windows.Controls.Canvas
