        Start-BfxAnim $tf.T $global:BfxP.Y -10 10 (Get-BfxRnd $S 0.8 1.4) (Get-BfxRnd $S) -Reverse -Ease
        [void]$flock.Children.Add((Set-BfxAt $bat (- (Get-BfxRnd $S 0 200)) (Get-BfxRnd $S (-$H * 0.3) ($H * 0.3))))
    }
    $ft = Set-BfxTransforms $flock 0 0
