    Add-BfxSpread $S {
        param($slot)
        $lamp = New-Object System.Windows.Controls.Canvas
        [void]$lamp.Children.Add((Set-BfxAt (New-BfxRect 1 ($ly - 6) (New-BfxBrush '#505050' 0.6)) 0 (-$ly)))
        $halo = New-BfxGlow ($H * 1.8) '#ffe8b0' 0.35; [void]$lamp.Children.Add($halo)
