        $per = Get-BfxRnd $S 1.8 2.6; $ph = Get-BfxRnd $S
        Start-BfxAnim $bt.S $global:BfxP.SX 1 1.15 ($per / 2) $ph -Reverse -Ease; Start-BfxAnim $bt.S $global:BfxP.SY 1 0.8 ($per / 2) $ph -Reverse -Ease
