function global:Add-BfxArrows {
    param([string]$BannerName, [double]$BannerH)
    $S = New-BfxStage $BannerName; if (-not $S) { return }; $H = $BannerH
    $shaft = New-BfxBrush '#d8c8a8' 1; $tipB = New-BfxBrush '#e8e8e8' 1; $flet = New-BfxBrush '#c84a3a' 1
    $per = 3.2; $volley = @()
    for ($i = 0; $i -lt 16; $i++) {
        $arrow = New-Object System.Windows.Controls.Canvas
        [void]$arrow.Children.Add((Set-BfxAt (New-BfxRect 24 1.2 $shaft) -14 -0.6))
        $tg = New-BfxGeo { param($c) $c.BeginFigure((New-BfxPoint 13 0), $true, $true); $c.LineTo((New-BfxPoint 8 -2.5), $true, $false); $c.LineTo((New-BfxPoint 8 2.5), $true, $false) }
        [void]$arrow.Children.Add((New-BfxPath $tg $tipB)); [void]$arrow.Children.Add((Set-BfxAt (New-BfxRect 4 5 $flet) -14 -2.5))
        $tf = Set-BfxTransforms $arrow 0 0
        $lag = Get-BfxRnd $S 0 0.2; $dy = Get-BfxRnd $S 0 18; $dx = Get-BfxRnd $S 0 140
        $ky = @(); for ($n = 0; $n -le 10; $n++) { $u = $n / 10.0; $ky += , @($u, ($H * 0.9 - [Math]::Sin($u * [Math]::PI) * $H * 0.75 + $dy)) }
        Start-BfxKeys $tf.T $global:BfxP.Y $ky ($per * 0.8) ((1 - $lag) % 1)
        Add-BfxItem $S $arrow -Fx 0 -Top 0
        $volley += , @($tf, $lag, $dx)
    }
    $S.Extra = { param($cw)
        foreach ($v in $volley) {
            $span = $cw + 200; $tf = $v[0]
            Start-BfxAnim $tf.T $global:BfxP.X (-60 - $v[2]) ($span - 60 - $v[2]) ($per * 0.8) ((1 - $v[1]) % 1)
            $ka = @(); for ($n = 0; $n -le 10; $n++) { $u = $n / 10.0; $ka += , @($u, ([Math]::Atan2(- [Math]::Cos($u * [Math]::PI) * $H * 0.75 * [Math]::PI, $span) * 180 / [Math]::PI)) }
            Start-BfxKeys $tf.R $global:BfxP.A $ka ($per * 0.8) ((1 - $v[1]) % 1)
        }
    }.GetNewClosure()
    Complete-BfxStage $S
}

function global:Add-BfxCheckered {
    param([string]$BannerName, [double]$BannerH)
    $S = New-BfxStage $BannerName; if (-not $S) { return }; $H = $BannerH
    $cell = 12.0
    $dg = New-Object System.Windows.Media.DrawingGroup
    [void]$dg.Children.Add([System.Windows.Media.GeometryDrawing]::new((New-BfxBrush '#f0f0f0' 0.16), $null, [System.Windows.Media.RectangleGeometry]::new([System.Windows.Rect]::new(0, 0, $cell * 2, $cell * 2))))
    [void]$dg.Children.Add([System.Windows.Media.GeometryDrawing]::new((New-BfxBrush '#0a0a0c' 0.3), $null, [System.Windows.Media.RectangleGeometry]::new([System.Windows.Rect]::new(0, 0, $cell, $cell))))
    [void]$dg.Children.Add([System.Windows.Media.GeometryDrawing]::new((New-BfxBrush '#0a0a0c' 0.3), $null, [System.Windows.Media.RectangleGeometry]::new([System.Windows.Rect]::new($cell, $cell, $cell, $cell))))
    $tile = New-Object System.Windows.Media.DrawingBrush $dg
    $tile.TileMode = [System.Windows.Media.TileMode]::Tile; $tile.Stretch = [System.Windows.Media.Stretch]::None
    $tile.ViewportUnits = [System.Windows.Media.BrushMappingMode]::Absolute; $tile.Viewport = [System.Windows.Rect]::new(0, 0, $cell * 2, $cell * 2)
    $tile.Freeze()
    $flag = New-BfxRect 4200 ($H + 24) $tile
    $sk = New-Object System.Windows.Media.SkewTransform 0, 0
    $flag.RenderTransform = $sk
    Start-BfxAnim $sk ([System.Windows.Media.SkewTransform]::AngleYProperty) -2.5 2.5 1.6 0 -Reverse -Ease
    Add-BfxItem $S $flag -Fx 0 -Top -12
    $sheen = New-BfxRect 90 ($H + 20) (New-BfxLinear @(@(0, '#ffffff', 0), @(0.5, '#ffffff', 0.14), @(1, '#ffffff', 0)) -Horizontal)
    $st = Set-BfxTransforms $sheen
    Add-BfxItem $S $sheen -Top -10 -Speed 160 -T $st.T -Margin 100
    Complete-BfxStage $S
}

function global:Add-BfxDriftsmoke {
    param([string]$BannerName, [double]$BannerH)
    $S = New-BfxStage $BannerName; if (-not $S) { return }; $H = $BannerH
    for ($i = 0; $i -lt 22; $i++) {
        $puff = New-BfxGlow 40 '#e8e8f0' 0.14; $tf = Set-BfxTransforms $puff
        $life = Get-BfxRnd $S 1.8 2.6; $ph = Get-BfxRnd $S
        Start-BfxAnim $tf.T $global:BfxP.X (Get-BfxRnd $S -10 10) (- (Get-BfxRnd $S 140 260)) $life $ph
        Start-BfxAnim $tf.T $global:BfxP.Y 0 (- (Get-BfxRnd $S 40 90)) $life $ph
        Start-BfxAnim $tf.S $global:BfxP.SX 0.5 3.2 $life $ph; Start-BfxAnim $tf.S $global:BfxP.SY 0.5 3.2 $life $ph
        Start-BfxKeys $puff $global:BfxP.O @(@(0, 0), @(0.1, 1), @(1, 0)) $life $ph
        Add-BfxItem $S $puff -Fx 0.7 -OffsetX (Get-BfxRnd $S -20 20) -Top $H
    }
    foreach ($ox in @(-30, 30)) { Add-BfxItem $S (New-BfxGlow 28 '#ff2a3a' 0.9) -Fx 0.7 -OffsetX $ox -Top ($H - 8) }
    Complete-BfxStage $S
}

function global:Add-BfxSumie {
    param([string]$BannerName, [double]$BannerH)
    $S = New-BfxStage $BannerName; if (-not $S) { return }; $H = $BannerH
    # Sumi-e ink brush strokes: painted in from left to right, held, then
    # fading out. Spread over the middle and right part of the width.
    $n = 7
    for ($i = 0; $i -lt $n; $i++) {
        $len = $H * (Get-BfxRnd $S 0.9 1.6); $wid = $H * (Get-BfxRnd $S 0.07 0.12); $bend = $len * (Get-BfxRnd $S -0.12 0.12)
        $red = ($i -eq 3)
        $hex = $(if ($red) { '#c8322a' } else { '#f2efe8' }); $alpha = $(if ($red) { 0.34 } else { 0.22 })
        $boxH = $wid * 3.0; $cy = $boxH / 2
        $pts = New-Object System.Collections.ArrayList
        for ($k = 0; $k -le 26; $k++) {
            $u = $k / 26.0
            $w = $(if ($u -lt 0.08) { $wid * (0.55 + 0.45 * ($u / 0.08)) } else { $wid * (1.0 - 0.9 * (($u - 0.08) / 0.92)) })
            $w = $w * (Get-BfxRnd $S 0.9 1.08)
            [void]$pts.Add(@(($len * $u), ($cy + $bend * [Math]::Sin([Math]::PI * $u)), $w))
        }
        $geo = New-BfxGeo { param($c)
            $c.BeginFigure((New-BfxPoint $pts[0][0] ($pts[0][1] - $pts[0][2] / 2)), $true, $true)
            for ($k = 1; $k -lt $pts.Count; $k++) { $c.LineTo((New-BfxPoint $pts[$k][0] ($pts[$k][1] - $pts[$k][2] / 2)), $true, $false) }
            for ($k = $pts.Count - 1; $k -ge 0; $k--) { $c.LineTo((New-BfxPoint $pts[$k][0] ($pts[$k][1] + $pts[$k][2] / 2)), $true, $false) }
        }.GetNewClosure()
        $holder = New-Object System.Windows.Controls.Canvas
        $holder.Width = $len * 1.12; $holder.Height = $boxH
        [void]$holder.Children.Add((New-BfxPath $geo (New-BfxBrush $hex $alpha)))
        # dry-brush bristles running out past the tail
        for ($b = 0; $b -lt 3; $b++) {
            $off = $wid * (Get-BfxRnd $S -0.3 0.3); $u0 = Get-BfxRnd $S 0.45 0.65
            $bgeo = New-BfxGeo { param($c)
                $c.BeginFigure((New-BfxPoint ($len * $u0) ($cy + $off + $bend * [Math]::Sin([Math]::PI * $u0))), $false, $false)
                $c.LineTo((New-BfxPoint ($len * 1.08) ($cy + $off * 0.6)), $true, $false)
            }.GetNewClosure()
            [void]$holder.Children.Add((New-BfxPath $bgeo $null (New-BfxBrush $hex ($alpha * 0.8)) (Get-BfxRnd $S 0.6 1.2)))
        }
        # a few ink drops near the start of the stroke
        for ($d = 0; $d -lt 3; $d++) {
            $ds = $wid * (Get-BfxRnd $S 0.12 0.28)
            $drop = New-BfxEllipse $ds $ds (New-BfxBrush $hex $alpha)
            [void]$holder.Children.Add((Set-BfxAt $drop ($len * (Get-BfxRnd $S 0.02 0.25)) ($cy + $wid * (Get-BfxRnd $S 0.7 1.3) * (Get-BfxPick $S @(1, -1)))))
        }
        # paint-in: a hard edge in the opacity mask moves along the stroke
        $mask = New-BfxLinear @(@(0, '#ffffff', 1), @(0, '#ffffff', 1), @(0.02, '#ffffff', 0), @(1, '#ffffff', 0)) -Horizontal -NoFreeze
        $holder.OpacityMask = $mask
        $per = Get-BfxRnd $S 8 12; $ph = Get-BfxRnd $S
        $offP = [System.Windows.Media.GradientStop]::OffsetProperty
        Start-BfxKeys $mask.GradientStops[1] $offP @(@(0, 0), @(0.05, 0), @(0.2, 1.0), @(1, 1.0)) $per $ph
        Start-BfxKeys $mask.GradientStops[2] $offP @(@(0, 0.02), @(0.05, 0.02), @(0.2, 1.04), @(1, 1.04)) $per $ph
        Start-BfxKeys $holder $global:BfxP.O @(@(0, 0), @(0.04, 0), @(0.05, 1), @(0.62, 1), @(0.8, 0), @(1, 0)) $per $ph
        $tf = Set-BfxTransforms $holder 0 0.5; $tf.R.Angle = Get-BfxRnd $S -14 14
        $fx = 0.28 + (($i + (Get-BfxRnd $S 0 0.8)) / $n) * 0.66
        Add-BfxItem $S $holder -Fx $fx -Top ($H * (Get-BfxRnd $S 0.22 0.78) - $cy)
    }
    Complete-BfxStage $S
}

function global:Add-BfxRunes {
    param([string]$BannerName, [double]$BannerH)
    $S = New-BfxStage $BannerName; if (-not $S) { return }; $H = $BannerH
    $glyphs = @(
        @(@(0, -1, 0, 1), @(0, -1, 0.6, -0.4)), @(@(0, -1, 0, 1), @(0, -0.2, 0.6, -0.8), @(0, 0.2, 0.6, 0.8)),
        @(@(-0.5, 1, 0, -1), @(0, -1, 0.5, 1), @(-0.3, 0.3, 0.3, 0.3)), @(@(0, -1, 0, 1), @(0, -1, 0.6, -0.4), @(0.6, -0.4, 0, 0.2)),
        @(@(-0.5, -1, 0.5, 1), @(0.5, -1, -0.5, 1)), @(@(0, -1, 0, 1), @(-0.5, -0.5, 0.5, 0.5)),
        @(@(-0.5, -1, -0.5, 1), @(0.5, -1, 0.5, 1), @(-0.5, -1, 0.5, 1)), @(@(0, -1, 0, 1), @(-0.6, -0.3, 0, -1), @(0.6, -0.3, 0, -1))
    )
    $ink = New-BfxBrush '#8cd2ff' 0.85
    for ($i = 0; $i -lt 16; $i++) {
        $sz = Get-BfxRnd $S 7 13; $gl = $glyphs[$S.R.Next(0, $glyphs.Count)]
        $geo = New-BfxGeo { param($c) foreach ($sg in $gl) { $c.BeginFigure((New-BfxPoint ($sg[0] * $sz) ($sg[1] * $sz)), $false, $false); $c.LineTo((New-BfxPoint ($sg[2] * $sz) ($sg[3] * $sz)), $true, $false) } }.GetNewClosure()
        $rune = New-BfxPath $geo $null $ink 1.6
        Set-BfxShadow $rune '#7fd0ff' 8
        $tf = Set-BfxTransforms $rune
        $per = ($H + 30) / (Get-BfxRnd $S 8 20); $ph = Get-BfxRnd $S
        Start-BfxAnim $tf.T $global:BfxP.Y ($H + 15) -15 $per $ph
        Start-BfxKeys $rune $global:BfxP.O @(@(0, 0), @(0.5, 1), @(1, 0)) $per $ph
        Start-BfxAnim $tf.T $global:BfxP.X -6 6 (Get-BfxRnd $S 6 11) (Get-BfxRnd $S) -Reverse -Ease
        Add-BfxItem $S $rune -Fx (Get-BfxRnd $S 0.05 0.95) -Top 0
    }
    Complete-BfxStage $S
}

function global:Add-BfxJungle {
    param([string]$BannerName, [double]$BannerH)
    $S = New-BfxStage $BannerName; if (-not $S) { return }; $H = $BannerH
    for ($i = 0; $i -lt 6; $i++) {
        $fl = New-BfxGlow 60 '#e8ffb0' 0.14
        Start-BfxAnim $fl $global:BfxP.O 0.4 1 (Get-BfxRnd $S 2 4) (Get-BfxRnd $S) -Reverse -Ease
        $tf = Set-BfxTransforms $fl; Start-BfxAnim $tf.T $global:BfxP.X -20 20 (Get-BfxRnd $S 6 10) (Get-BfxRnd $S) -Reverse -Ease
        Add-BfxItem $S $fl -Fx (0.2 + $i * 0.13) -Top ($H * (Get-BfxRnd $S 0.2 0.7))
    }
    $stem = New-BfxBrush '#143c1e' 0.95; $leafB = New-BfxBrush '#1e5a28' 0.85
    $len = $H * 0.95
    foreach ($fr in @(@(0, 0.1, 40, 1), @(0, 1.0, -34, 1), @(1, 0.05, 140, -1), @(1, 0.95, 209, -1))) {
        $geo = New-BfxGeo { param($c)
            $c.BeginFigure((New-BfxPoint 0 0), $false, $false); $c.QuadraticBezierTo((New-BfxPoint ($len * 0.6) ($len * -0.18)), (New-BfxPoint $len 0), $true, $false)
            for ($k = 1; $k -lt 14; $k++) { $u = $k / 14.0; $px = $len * $u; $py = -0.36 * $len * $u * (1 - $u); $lfl = $len * 0.35 * [Math]::Sin($u * [Math]::PI)
                foreach ($sd in @(-1, 1)) { $c.BeginFigure((New-BfxPoint $px $py), $false, $false); $c.LineTo((New-BfxPoint ($px + [Math]::Cos($sd * 1.1) * $lfl * 0.45) ($py + [Math]::Sin($sd * 1.1) * $lfl)), $true, $false) } }
        }.GetNewClosure()
        $grp = New-Object System.Windows.Controls.Canvas
        [void]$grp.Children.Add((New-BfxPath $geo $null $leafB 3)); [void]$grp.Children.Add((New-BfxPath $geo $null $stem 1.2))
        $tf = Set-BfxTransforms $grp 0 0; $tf.R.Angle = $fr[2]
        Start-BfxAnim $tf.R $global:BfxP.A ($fr[2] - 6) ($fr[2] + 6) (Get-BfxRnd $S 3 5) (Get-BfxRnd $S) -Reverse -Ease
        Add-BfxItem $S $grp -Fx $fr[0] -Top ($H * $fr[1])
    }
    Complete-BfxStage $S
}

function global:Add-BfxSkulls {
    param([string]$BannerName, [double]$BannerH)
    $S = New-BfxStage $BannerName; if (-not $S) { return }; $H = $BannerH
    $dark = New-BfxBrush '#14040a' 1
    for ($i = 0; $i -lt 6; $i++) {
        $sz = Get-BfxRnd $S 10 18
        $grp = New-Object System.Windows.Controls.Canvas
        [void]$grp.Children.Add((New-BfxGlow ($sz * 6) '#ff3a1a' 0.35))
        $geo = New-BfxGeo { param($c)
            $c.BeginFigure((New-BfxPoint (-$sz) 0), $true, $true); $c.ArcTo((New-BfxPoint $sz 0), [System.Windows.Size]::new($sz, $sz), 0, $false, [System.Windows.Media.SweepDirection]::Clockwise, $true, $false)
            foreach ($q in @(@(0.8, 0.6), @(0.4, 0.6), @(0.4, 0.9), @(-0.4, 0.9), @(-0.4, 0.6), @(-0.8, 0.6))) { $c.LineTo((New-BfxPoint ($q[0] * $sz) ($q[1] * $sz)), $true, $false) }
        }.GetNewClosure()
        [void]$grp.Children.Add((New-BfxPath $geo (New-BfxBrush '#ff7850' 0.8)))
        foreach ($ex in @(-0.38, 0.38)) { [void]$grp.Children.Add((Set-BfxAt (New-BfxEllipse ($sz * 0.48) ($sz * 0.56) $dark) (($ex - 0.24) * $sz) (-0.23 * $sz))) }
        $ng = New-BfxGeo { param($c) $c.BeginFigure((New-BfxPoint 0 ($sz * 0.3)), $true, $true); $c.LineTo((New-BfxPoint (-$sz * 0.1) ($sz * 0.5)), $true, $false); $c.LineTo((New-BfxPoint ($sz * 0.1) ($sz * 0.5)), $true, $false) }.GetNewClosure()
        [void]$grp.Children.Add((New-BfxPath $ng $dark))
        $tf = Set-BfxTransforms $grp 0 0
        $per = Get-BfxRnd $S 4 8; $ph = Get-BfxRnd $S
        Start-BfxAnim $tf.T $global:BfxP.Y 0 -14 $per $ph
        Start-BfxKeys $grp $global:BfxP.O @(@(0, 0), @(0.5, 1), @(1, 0)) $per $ph
        Add-BfxItem $S $grp -Fx (Get-BfxRnd $S 0.03 0.95) -Top ($H * (Get-BfxRnd $S 0.3 0.7))
    }
    Complete-BfxStage $S
}



# ------------------------------------------------------------
# Round 3 effects (game-specific, part 1)
# ------------------------------------------------------------

function global:Add-BfxManuscript {
    param([string]$BannerName, [double]$BannerH)
    $S = New-BfxStage $BannerName; if (-not $S) { return }; $H = $BannerH
    $paper = New-BfxBrush '#ece8dc' 0.9; $ink = New-BfxBrush '#28282e' 0.75
    for ($i = 0; $i -lt 9; $i++) {
        $page = New-Object System.Windows.Controls.Canvas
        [void]$page.Children.Add((Set-BfxAt (New-BfxRect 22 28 $paper) -11 -14))
        $typeSec = Get-BfxRnd $S 4.5 6.5; $tph = Get-BfxRnd $S
        for ($n = 0; $n -lt 7; $n++) {
            $ln = New-BfxRect $(if ($n -eq 6) { 9 } else { 16 }) 1.2 $ink
            $on = ($n + 1) / 8.0
            Start-BfxKeys $ln $global:BfxP.O @(@(0, 0), @($on, 0), @(($on + 0.001), 1), @(0.97, 1), @(0.975, 0), @(1, 0)) $typeSec $tph -Discrete
            [void]$page.Children.Add((Set-BfxAt $ln -8 (-10 + $n * 3.4)))
        }
        $tf = Set-BfxTransforms $page 0 0
        $ph = Get-BfxRnd $S
        Start-BfxAnim $tf.T $global:BfxP.Y -40 ($H + 40) (($H + 80) / (Get-BfxRnd $S 10 22)) $ph
        Start-BfxAnim $tf.T $global:BfxP.X -14 14 (Get-BfxRnd $S 4 7) (Get-BfxRnd $S) -Reverse -Ease
        $base = Get-BfxRnd $S -18 18
        Start-BfxAnim $tf.R $global:BfxP.A ($base - 14) ($base + 14) (Get-BfxRnd $S 3 5) (Get-BfxRnd $S) -Reverse -Ease
        Start-BfxAnim $tf.S $global:BfxP.SY 1 0.55 (Get-BfxRnd $S 2.5 4) (Get-BfxRnd $S) -Reverse -Ease
        Add-BfxItem $S $page -Fx (Get-BfxRnd $S 0.05 0.95) -Top 0
    }
    Complete-BfxStage $S
}

function global:Add-BfxTendrils {
    param([string]$BannerName, [double]$BannerH)
    $S = New-BfxStage $BannerName; if (-not $S) { return }; $H = $BannerH
    Add-BfxItem $S (New-BfxGlow ($H * 2.2) '#cfe0ff' 0.1) -Fx 0.55 -Top ($H * 0.5)
    $smoke = New-BfxBrush '#040408' 0.85
    for ($i = 0; $i -lt 9; $i++) {
        $side = $i % 3; $len = $(if ($side -eq 2) { $H * (Get-BfxRnd $S 0.6 1.0) } else { $H * (Get-BfxRnd $S 1.2 2.2) })
        $wob = Get-BfxRnd $S 0 6.28
        $geo = New-BfxGeo { param($c)
            $pts = @(); $a = 0.0; $x = 0.0; $y = 0.0
            for ($n = 0; $n -le 16; $n++) { $u = $n / 16.0; $a = [Math]::Sin($u * 5 + $wob) * 0.5; $pts += , @($x, $y, (9 * (1 - $u) + 0.8), $a); $x += [Math]::Cos($a) * $len / 16; $y += [Math]::Sin($a) * $len / 16 }
            $c.BeginFigure((New-BfxPoint $pts[0][0] ($pts[0][1] - $pts[0][2])), $true, $true)
            foreach ($p in $pts) { $c.LineTo((New-BfxPoint ($p[0] - [Math]::Sin($p[3]) * $p[2]) ($p[1] - [Math]::Cos($p[3]) * $p[2])), $true, $true) }
            for ($n = $pts.Count - 1; $n -ge 0; $n--) { $p = $pts[$n]; $c.LineTo((New-BfxPoint ($p[0] + [Math]::Sin($p[3]) * $p[2]) ($p[1] + [Math]::Cos($p[3]) * $p[2])), $true, $true) }
        }.GetNewClosure()
        $ten = New-BfxPath $geo $smoke
        $bl = New-Object System.Windows.Media.Effects.BlurEffect; $bl.Radius = 3; $ten.Effect = $bl
        $tf = Set-BfxTransforms $ten
        $tf.R.Angle = $(switch ($side) { 0 { 0 } 1 { 180 } default { -90 } }) + (Get-BfxRnd $S -15 15)
        Start-BfxAnim $tf.S $global:BfxP.SX 0.45 1 (Get-BfxRnd $S 5 9) (Get-BfxRnd $S) -Reverse -Ease
        Start-BfxAnim $tf.S $global:BfxP.SY 0.7 1.25 (Get-BfxRnd $S 2 4) (Get-BfxRnd $S) -Reverse -Ease
        if ($side -eq 2) { Add-BfxItem $S $ten -Fx (Get-BfxRnd $S 0.05 0.95) -Top ($H + 2) }
        else { Add-BfxItem $S $ten -Fx $(if ($side -eq 0) { 0 } else { 1 }) -OffsetX $(if ($side -eq 0) { -2 } else { 2 }) -Top ($H * (Get-BfxRnd $S 0.1 0.9)) }
    }
    Complete-BfxStage $S
}

function global:Add-BfxScope {
    param([string]$BannerName, [double]$BannerH)
    $S = New-BfxStage $BannerName; if (-not $S) { return }; $H = $BannerH
    $rad = $H * 0.42; $big = 4200.0
    $sc = New-Object System.Windows.Controls.Canvas
    $vg = New-BfxGeo -EvenOdd { param($c)
        $c.BeginFigure((New-BfxPoint (-$big) (-$big)), $true, $true); $c.LineTo((New-BfxPoint $big (-$big)), $true, $false); $c.LineTo((New-BfxPoint $big $big), $true, $false); $c.LineTo((New-BfxPoint (-$big) $big), $true, $false)
        $c.BeginFigure((New-BfxPoint $rad 0), $true, $true); $c.ArcTo((New-BfxPoint (-$rad) 0), [System.Windows.Size]::new($rad, $rad), 0, $false, [System.Windows.Media.SweepDirection]::Clockwise, $true, $false); $c.ArcTo((New-BfxPoint $rad 0), [System.Windows.Size]::new($rad, $rad), 0, $false, [System.Windows.Media.SweepDirection]::Clockwise, $true, $false)
    }.GetNewClosure()
    [void]$sc.Children.Add((New-BfxPath $vg (New-BfxBrush '#000000' 0.45)))
    $ink = New-BfxBrush '#0a0a0a' 0.85
    $thin = New-BfxGeo { param($c) $c.BeginFigure((New-BfxPoint (-$rad) 0), $false, $false); $c.LineTo((New-BfxPoint $rad 0), $true, $false); $c.BeginFigure((New-BfxPoint 0 (-$rad)), $false, $false); $c.LineTo((New-BfxPoint 0 $rad), $true, $false) }.GetNewClosure()
    [void]$sc.Children.Add((New-BfxPath $thin $null $ink 1.2))
    $thick = New-BfxGeo { param($c) foreach ($q in @(@(-1, 0), @(1, 0), @(0, 1))) { $c.BeginFigure((New-BfxPoint ($q[0] * $rad * 0.35) ($q[1] * $rad * 0.35)), $false, $false); $c.LineTo((New-BfxPoint ($q[0] * $rad) ($q[1] * $rad)), $true, $false) } }.GetNewClosure()
    [void]$sc.Children.Add((New-BfxPath $thick $null $ink 3))
