        $col = $(if ($i % 2) { '#ff8a20' } else { '#2a8aff' }); $per = Get-BfxRnd $S 9 14; $ph = Get-BfxRnd $S
        $bl = @(); for ($n = 0; $n -lt 8; $n++) { $bl += (Get-BfxRnd $S 0.7 1.2) }
