            Start-BfxKeys $drt.T $global:BfxP.Y @(@(0, 0), @(0.05, 0), @(0.92, ($len * 0.87)), @(1, ($len * 0.87))) $per $ph
            [void]$grp.Children.Add((Set-BfxAt $drop ($dx - 3) -3))
